## 2. KNOWLEDGE GRAPH SCHEMA

```cypher
CREATE CONSTRAINT party_id IF NOT EXISTS FOR (p:Party) REQUIRE p.id IS UNIQUE;
CREATE CONSTRAINT doc_id IF NOT EXISTS FOR (d:Document) REQUIRE d.id IS UNIQUE;
CREATE CONSTRAINT sanction_id IF NOT EXISTS FOR (s:SanctionList) REQUIRE s.id IS UNIQUE;

CREATE INDEX party_jurisdiction FOR (p:Party) ON (p.country);
CREATE INDEX sanction_list FOR (s:SanctionList) ON (s.list_name);

// Party:        {id, name, type:INDIVIDUAL|COMPANY|TRUST, country, lei_number, risk_score:0-100, is_pep:bool}
// Document:     {id, type:PASSPORT|INCORPORATION|UTILITY_BILL|TAX_RETURN, verification:VERIFIED|PENDING|EXPIRED}
// SanctionList: {id, list_name:OFAC|EU|UN|HMT, entity_name, match_type:EXACT|FUZZY|ALIAS, risk_category:HIGH|MEDIUM|LOW}

// Relationships
// (p1:Party)-[:RELATED_TO {type:'DIRECTOR|UBO|BENEFICIAL_OWNER|SUBSIDIARY', ownership_pct:0.0-1.0}]->(p2:Party)
// (p:Party)-[:MATCHES {confidence:0.0-1.0, method:'EXACT|FUZZY|ALIAS'}]->(s:SanctionList)

CALL gds.graph.project('kyc_graph', ['Party','SanctionList'], {
  RELATED_TO:{orientation:'NATURAL', properties:['ownership_pct']},
  MATCHES:{orientation:'UNDIRECTED', properties:['confidence']}
});
```
